#include <vector>
#include <string>
#include <sstream>

using namespace std;

class Solution {
    int n;
    vector<vector<int>> adj;
    vector<int> tin, tout;
    int timer;
    vector<int> depth;
    int max_depth;
    vector<vector<int>> up_table;

    struct FenwickXor {
        int size;
        vector<int> tree;
        FenwickXor(int n) : size(n), tree(n + 2, 0) {}

        void add(int i, int val) {
            for (; i <= size; i += i & -i) {
                tree[i] ^= val;
            }
        }

        void range_xor(int l, int r, int val) {
            add(l, val);
            add(r + 1, val);
        }

        int query(int i) {
            int res = 0;
            for (; i > 0; i -= i & -i) {
                res ^= tree[i];
            }
            return res;
        }
    };

    void dfs(int v, int p, int d) {
        tin[v] = ++timer;
        depth[v] = d;
        up_table[v][0] = p;
        for (int u : adj[v]) {
            if (u != p) {
                dfs(u, v, d + 1);
            }
        }
        tout[v] = timer;
    }

    int get_lca(int u, int v) {
        if (depth[u] < depth[v]) swap(u, v);
        for (int j = max_depth - 1; j >= 0; --j) {
            if (depth[u] - (1 << j) >= depth[v]) {
                u = up_table[u][j];
            }
        }
        if (u == v) return u;
        for (int j = max_depth - 1; j >= 0; --j) {
            if (up_table[u][j] != up_table[v][j]) {
                u = up_table[u][j];
                v = up_table[v][j];
            }
        }
        return up_table[u][0];
    }

public:
    vector<bool> palindromePath(int n, vector<vector<int>>& edges, string s, vector<string>& queries) {
        this->n = n;
        adj.assign(n, vector<int>());
        for (const auto& edge : edges) {
            adj[edge[0]].push_back(edge[1]);
            adj[edge[1]].push_back(edge[0]);
        }

        tin.resize(n);
        tout.resize(n);
        depth.resize(n);
        timer = 0;

        max_depth = 1;
        while ((1 << max_depth) <= n) max_depth++;
        up_table.assign(n, vector<int>(max_depth, 0));

        dfs(0, 0, 0);

        for (int j = 1; j < max_depth; ++j) {
            for (int i = 0; i < n; ++i) {
                up_table[i][j] = up_table[up_table[i][j - 1]][j - 1];
            }
        }

        FenwickXor bit(n + 1);

        for (int i = 0; i < n; ++i) {
            bit.range_xor(tin[i], tout[i], 1 << (s[i] - 'a'));
        }

        vector<bool> ans;
        for (const string& q_str : queries) {
            stringstream ss(q_str);
            string type;
            ss >> type;
            if (type == "update") {
                int u;
                char c;
                ss >> u >> c;
                if (s[u] != c) {
                    int diff = (1 << (s[u] - 'a')) ^ (1 << (c - 'a'));
                    s[u] = c;
                    bit.range_xor(tin[u], tout[u], diff);
                }
            } else {
                int u, v;
                ss >> u >> v;
                int lca = get_lca(u, v);
                int mask = bit.query(tin[u]) ^ bit.query(tin[v]) ^ (1 << (s[lca] - 'a'));
                ans.push_back((mask & (mask - 1)) == 0);
            }
        }

        return ans;
    }
};
